    nodes = extract_nodes(instance)
    ids = infer_ids(instance, nodes)
    if depot in ids:
        ids = [i for i in ids if i != depot]
    demands = get_demands(instance, ids, depot)
    coords = build_coords(instance, nodes, ids, depot)

    # Constructive: angle/sweep if coordinates exist, else deterministic by demand then id.
    if coords.get(depot) is not None and any(coords.get(i) is not None for i in ids):
        dx0, dy0 = coords[depot]
        ordered = []
        for i in ids:
            c = coords.get(i)
            if c is None:
                ang = 0
                rad = 0
            else:
                dx = c[0] - dx0
                dy = c[1] - dy0
                ang = dy / (abs(dx) + abs(dy) + 1e-12)
                if dx < 0:
                    ang -= 2
                rad = dx * dx + dy * dy
            ordered.append((ang, rad, i))
        ordered.sort()
        ordered = [i for _, _, i in ordered]
    else:
        ordered = sorted(ids, key=lambda i: (demands.get(i, 0), i))

    routes = []
    cur = []
    cur_load = 0
    for i in ordered:
        d = demands.get(i, 0)
        if capacity is not None and cur and cur_load + d > capacity:
            routes.append(cur)
            cur = [i]
            cur_load = d
        else:
            cur.append(i)
            cur_load += d
    if cur:
        routes.append(cur)

    # Repair: if any singleton exceeds capacity, keep it and continue (assumes feasible instance).
    # Local search 1: intra-route 2-opt.
    if coords.get(depot) is not None:
        improved = True
        while improved:
            improved = False
            for r in range(len(routes)):
                route = routes[r]
                n = len(route)
                if n < 4:
                    continue
                best_gain = 0
                best_i = best_j = None
                base = route_cost(route)
                for i in range(n - 2):
                    a = depot if i == 0 else route[i - 1]
                    b = route[i]
                    for j in range(i + 2, n):
                        c = route[j - 1]
                        d = depot if j == n else route[j]
                        gain = dist(a, b) + dist(c, d) - dist(a, c) - dist(b, d)
                        if gain > best_gain + 1e-12:
                            best_gain = gain
                            best_i, best_j = i, j
                if best_i is not None:
                    route[best_i:best_j] = reversed(route[best_i:best_j])
                    improved = True

    # Local search 2: relocate/swap between routes.
    if coords.get(depot) is not None:
        changed = True
        while changed:
            changed = False
            best_move = None
            best_delta = 1e-12
            m = len(routes)
            for r1 in range(m):
                A = routes[r1]
                if not A:
                    continue
                loadA = route_demand(A)
                for idx, x in enumerate(A):
                    ax = depot if idx == 0 else A[idx - 1]
                    bx = x
                    cx = depot if idx == len(A) - 1 else A[idx + 1]
                    remove_delta_base = dist(ax, bx) + dist(bx, cx) - dist(ax, cx)
                    for r2 in range(m):
                        B = routes[r2]
                        loadB = route_demand(B)
                        # relocate x into B
                        if r1 != r2 and (capacity is None or loadB + demands.get(x, 0) <= capacity):
                            for pos in range(len(B) + 1):
                                l = depot if pos == 0 else B[pos - 1]
                                r = depot if pos == len(B) else B[pos]
                                add_delta = dist(l, x) + dist(x, r) - dist(l, r)
                                delta = remove_delta_base - add_delta
                                if delta > best_delta:
                                    best_delta = delta
                                    best_move = ("relocate", r1, idx, r2, pos)
                        # swap with y in B
                        if r2 >= r1:
                            for j, y in enumerate(B):
                                if r1 == r2 and idx == j:
                                    continue
                                new_loadA = loadA - demands.get(x, 0) + demands.get(y, 0)
                                new_loadB = loadB - demands.get(y, 0) + demands.get(x, 0)
                                if capacity is not None and (new_loadA > capacity or new_loadB > capacity):
                                    continue
                                a1 = depot if idx == 0 else A[idx - 1]
                                b1 = x
                                c1 = depot if idx == len(A) - 1 else A[idx + 1]
                                a2 = depot if j == 0 else B[j - 1]
                                b2 = y
                                c2 = depot if j == len(B) - 1 else B[j + 1]
                                old = dist(a1, b1) + dist(b1, c1) + dist(a2, b2) + dist(b2, c2)
                                new = dist(a1, y) + dist(y, c1) + dist(a2, x) + dist(x, c2)
                                delta = old - new
                                if delta > best_delta:
                                    best_delta = delta
                                    best_move = ("swap", r1, idx, r2, j)
            if best_move:
                if best_move[0] == "relocate":
                    _, r1, idx, r2, pos = best_move
                    x = routes[r1].pop(idx)
                    if r1 == r2 and pos > idx:
                        pos -= 1
                    routes[r2].insert(pos, x)
                else:
                    _, r1, idx, r2, j = best_move
                    routes[r1][idx], routes[r2][j] = routes[r2][j], routes[r1][idx]
                changed = True

    # Cleanup empties and ensure all customers exactly once by deduplicating construction order if needed.
    seen = {}
    final_routes = []
    for r in routes:
        rr = []
        load = 0
        for i in r:
            if i != depot and not seen.get(i, False):
                seen[i] = True
                rr.append(i)
                load += demands.get(i, 0)
        if rr:
            final_routes.append(rr)

